package com.bananalab.lite;
import java.util.*;import org.json.*;
/** Estado de escena compartido; editar un actor conserva los demas. */
final class SceneDraft {
 static final class Actor{String voice="media";String designId=java.util.UUID.randomUUID().toString().replace("-",""),name,kind,label="",look="",relation="",reference="",view="front";float x,y=67,size=1;boolean behind;Actor(String n,float px){name=n;kind=n;x=px;}String display(){return label.isEmpty()?kind:label;}}
 static final class Line{String actor,text;int slot;Line(String a,int s,String t){actor=a;slot=s;text=t;}}
 final List<Line> dialogue=new ArrayList<>();float beatSeconds=1.5f;boolean fixedDuration=false;
 static final class Prop{String id,type,holder="";boolean open=false;float x=76,y=67;Prop(String id,String type,float x){this.id=id;this.type=type;this.x=x;}}
 final List<Prop> props=new ArrayList<>();final List<String> targets=new ArrayList<>(),recipients=new ArrayList<>();
 Prop prop(String id){for(Prop p:props)if(p.id.equals(id))return p;return null;}
 Actor reference(String value){Actor found=null;for(Actor a:cast)if(a.name.equals(value)||a.label.equals(value)||a.kind.equals(value)){if(found!=null&&found!=a)return null;found=a;}return found;}
 String recipient(int i){return i<recipients.size()?recipients.get(i):"";}
 String target(int i){return i<targets.size()?targets.get(i):"";}
 final List<Actor> cast=new ArrayList<>();final List<String> actions=new ArrayList<>();final List<Integer> actors=new ArrayList<>(),slots=new ArrayList<>();boolean sound=false,sceneryTree=false;String lighting="auto";float fog=0;String setting="parque",focused="",previousFocus="",camera="auto";
 Actor get(String name){for(Actor a:cast)if(a.name.equals(name))return a;return null;}
 static SceneDraft fromPlan(OwnPlan plan){SceneDraft draft=new SceneDraft();for(int i=0;i<plan.names.size();i++){Actor a=new Actor(plan.names.get(i),(i+1)*100f/(plan.names.size()+1));a.look=plan.looks.get(i);draft.cast.add(a);draft.focused=a.name;}draft.setting=plan.setting;draft.actions.addAll(plan.actions);draft.actors.addAll(plan.actors);draft.slots.addAll(plan.slots);return draft;}
 int slot(int i){return i<slots.size()?slots.get(i):i;}
 String text(){StringBuilder b=new StringBuilder();for(Actor a:cast){if(b.length()>0)b.append(" y un ");b.append(a.kind).append(' ').append(a.look);}return b.append("; ").append(setting).toString();}
 String describe(){StringBuilder b=new StringBuilder("Escena compartida · ").append(setting).append(" · luz ").append(lighting).append(fog>0?" · niebla":"").append(sceneryTree?" · árbol en fondo":"");for(Actor a:cast)b.append("\n").append(a.label.isEmpty()?a.kind:a.label+" ("+a.kind+")").append(": ").append(a.look.isEmpty()?"aspecto original":a.look).append(", ").append(a.x<36?"izquierda":a.x>64?"derecha":"centro").append(a.size<.9?", pequeno":a.size>1.1?", grande":"").append(a.relation.isEmpty()?"":", "+a.relation).append(a.view.equals("front")?"":" · vista "+a.view);for(Prop p:props)b.append("\nObjeto: ").append(p.type).append(p.type.equals("puerta")?(p.open?" abierta al inicio":" cerrada al inicio"):"");for(int i=0;i<actions.size();i++)b.append("\n").append(i+1).append(". [tiempo ").append(slot(i)+1).append("] ").append(cast.get(actors.get(i)).label.isEmpty()?cast.get(actors.get(i)).name:cast.get(actors.get(i)).label).append(' ').append(Timeline.label(actions.get(i))).append(target(i).isEmpty()?"":" → "+target(i)).append(recipient(i).isEmpty()?"":" con "+get(recipient(i)).display());for(Line l:dialogue)b.append("\nDiálogo [tiempo ").append(l.slot+1).append("] ").append(get(l.actor).display()).append(": «").append(l.text).append("» · voz ").append(get(l.actor).voice);b.append("\nDuración: ").append(SceneTiming.seconds(this)).append(" s");return b.append("\nCámara: ").append(camera.equals("auto")?"automática":camera.equals("wide")?"general":camera.substring(camera.indexOf(':')+1)).append(sound?" · con ambiente":"").toString();}
 JSONObject json()throws JSONException{JSONObject out=new JSONObject().put("beatSeconds",beatSeconds).put("fixedDuration",fixedDuration).put("setting",setting).put("focused",focused).put("previousFocus",previousFocus).put("camera",camera).put("sound",sound).put("lighting",lighting).put("fog",fog).put("sceneryTree",sceneryTree);JSONArray chars=new JSONArray(),steps=new JSONArray();for(Actor a:cast)chars.put(new JSONObject().put("name",a.name).put("designId",a.designId).put("voice",a.voice).put("kind",a.kind).put("view",a.view).put("reference",a.reference).put("label",a.label).put("look",a.look).put("x",a.x).put("y",a.y).put("size",a.size).put("behind",a.behind).put("relation",a.relation));for(int i=0;i<actions.size();i++)steps.put(new JSONObject().put("actor",actors.get(i)).put("action",actions.get(i)).put("slot",slot(i)).put("target",target(i)).put("recipient",recipient(i)));JSONArray objects=new JSONArray();for(Prop p:props)objects.put(new JSONObject().put("id",p.id).put("type",p.type).put("holder",p.holder).put("open",p.open).put("x",p.x).put("y",p.y));JSONArray lines=new JSONArray();for(Line l:dialogue)lines.put(new JSONObject().put("actor",l.actor).put("slot",l.slot).put("text",l.text));return out.put("dialogue",lines).put("cast",chars).put("steps",steps).put("props",objects);}
 static SceneDraft read(String data)throws JSONException{JSONObject in=new JSONObject(data);SceneDraft d=new SceneDraft();d.setting=in.optString("setting","parque");d.focused=in.optString("focused");d.previousFocus=in.optString("previousFocus","");d.lighting=in.optString("lighting","auto");d.fog=(float)in.optDouble("fog",0);d.sceneryTree=in.optBoolean("sceneryTree",false);if(!d.lighting.matches("auto|day|night|warm")||Float.isNaN(d.fog)||d.fog<0||d.fog>.5f)throw new JSONException("Ambiente invalido");d.sound=in.optBoolean("sound",false);d.camera=in.optString("camera","auto");if(!d.camera.matches("auto|wide|(?:follow|close):(?:[a-z][a-z0-9_ ]{0,39})"))throw new JSONException("Camara invalida");JSONArray cast=in.getJSONArray("cast"),steps=in.getJSONArray("steps");if(cast.length()>4||steps.length()>SceneTiming.MAX_ACTIONS)throw new JSONException("Escena fuera de limites");for(int i=0;i<cast.length();i++){JSONObject row=cast.getJSONObject(i);String n=row.getString("name");if(!n.matches("[a-z][a-z0-9_ ]{0,39}")||d.get(n)!=null)throw new JSONException("Actor invalido");Actor a=new Actor(n,(float)row.optDouble("x",50));a.y=(float)row.optDouble("y",67);a.size=(float)row.optDouble("size",1);if(Float.isNaN(a.x)||a.x<12||a.x>88||Float.isNaN(a.y)||a.y<40||a.y>82||Float.isNaN(a.size)||a.size<.45||a.size>1.4)throw new JSONException("Posicion invalida");a.voice=row.optString("voice","media");if(!a.voice.matches("media|grave|aguda|robotica"))throw new JSONException("Voz invalida");a.kind=row.optString("kind",n);a.view=row.optString("view","front");if(!a.view.matches("front|right|left|back"))throw new JSONException("Vista invalida");a.reference=row.optString("reference","");if(!a.reference.isEmpty()&&!a.reference.matches("[a-z0-9_-]{1,60}"))throw new JSONException("Referencia invalida");a.label=row.optString("label");a.designId=row.optString("designId","legacy_"+Integer.toHexString((a.kind+"|"+a.label+"|"+n).hashCode()));if(!a.designId.matches("[a-z0-9_-]{1,60}"))throw new JSONException("Identidad invalida");if(!a.label.isEmpty()&&!a.label.matches("[a-z][a-z ]{0,29}"))throw new JSONException("Nombre invalido");a.look=row.optString("look");a.relation=row.optString("relation");a.behind=row.optBoolean("behind");d.cast.add(a);Knowledge.generic(n);}JSONArray objects=in.optJSONArray("props");if(objects!=null){if(objects.length()>6)throw new JSONException("Demasiados objetos");for(int i=0;i<objects.length();i++){JSONObject row=objects.getJSONObject(i);String id=row.getString("id"),type=row.getString("type");if(!id.matches("[a-z][a-z0-9_]{0,30}")||d.prop(id)!=null||!type.matches("puerta|mesa|silla|caja|lampara"))throw new JSONException("Objeto invalido");Prop p=new Prop(id,type,(float)row.optDouble("x",76));p.y=(float)row.optDouble("y",67);p.open=row.optBoolean("open",false);p.holder=row.optString("holder","");if(!p.holder.isEmpty()&&d.get(p.holder)==null)throw new JSONException("Portador inexistente");if((Float.isNaN(p.x)||Float.isInfinite(p.x))||p.x<10||p.x>90||(Float.isNaN(p.y)||Float.isInfinite(p.y))||p.y<40||p.y>82)throw new JSONException("Posicion de objeto invalida");d.props.add(p);}}
 for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);int a=step.getInt("actor");String action=step.getString("action");if(a<0||a>=d.cast.size()||!action.matches("camina|salta|baila|habla|saluda|acerca|gira|duerme|vuela|nada|aplaude|corre|canta|espera|entraizq|entrader|saleizq|saleder|mira|abre|sorprende|sienta|sostiene|acercaactor|entrega|recibe|besa|recibebeso"))throw new JSONException("Paso invalido");int slot=step.optInt("slot",i);if(slot<0||slot>=SceneTiming.MAX_BEATS)throw new JSONException("Tiempo invalido");for(int j=0;j<d.slots.size();j++)if(d.slots.get(j)==slot&&d.actors.get(j)==a)throw new JSONException("Acciones superpuestas del mismo personaje");String target=step.optString("target","");if(!target.isEmpty()&&d.prop(target)==null)throw new JSONException("Objeto de accion inexistente");if(action.equals("abre")&&(d.prop(target)==null||!d.prop(target).type.equals("puerta")))throw new JSONException("Abrir requiere puerta");String recipient=step.optString("recipient","");if(!recipient.isEmpty()&&(d.get(recipient)==null||recipient.equals(d.cast.get(a).name)))throw new JSONException("Destinatario invalido");if(action.matches("entrega|recibe")&&(recipient.isEmpty()||d.prop(target)==null||!d.prop(target).type.matches("caja|lampara")))throw new JSONException("Entrega requiere objeto portable y destinatario");if(action.matches("acercaactor|besa|recibebeso")&&recipient.isEmpty())throw new JSONException("Acercamiento requiere destinatario");d.recipients.add(recipient);d.targets.add(target);d.slots.add(slot);d.actors.add(a);d.actions.add(action);}d.beatSeconds=(float)in.optDouble("beatSeconds",Math.max(1.5,3.0/ObjectTransfer.beats(d)));d.fixedDuration=in.optBoolean("fixedDuration",false);if(Float.isNaN(d.beatSeconds)||Float.isInfinite(d.beatSeconds)||d.beatSeconds<.01f||SceneTiming.seconds(d)>SceneTiming.MAX_SECONDS+.01f)throw new JSONException("Duracion fuera de limites");JSONArray lines=in.optJSONArray("dialogue");if(lines!=null){if(lines.length()>32)throw new JSONException("Demasiados dialogos");Set<String> seen=new HashSet<>();for(int i=0;i<lines.length();i++){JSONObject x=lines.getJSONObject(i);String actor=x.getString("actor"),text=x.getString("text");int slot=x.getInt("slot");if(d.get(actor)==null||text.trim().isEmpty()||text.length()>120||!seen.add(actor+"|"+slot))throw new JSONException("Dialogo invalido");boolean talks=false;for(int j=0;j<d.actions.size();j++)talks|=d.cast.get(d.actors.get(j)).name.equals(actor)&&d.slot(j)==slot&&d.actions.get(j).equals("habla");if(!talks)throw new JSONException("El dialogo requiere una accion de hablar en su tiempo");d.dialogue.add(new Line(actor,slot,text));}}return d;}
 SceneDraft copy()throws JSONException{return read(json().toString());}
}
